// Trae las ofertas crudas de las empresas que publican en Workday.
// Su API es POST y pagina de a 20, por eso no entra en el nodo HTTP común.
// Las empresas se consultan en paralelo, de a tandas, para que no tarde tanto.
const SEARCH_TERMS = ['engineer', 'developer', 'architect'];
const PAGE_SIZE = 20;      // Workday devuelve vacío si se pide más de 20
const MAX_PAGES = 3;       // tope por término: 60 ofertas
const CONCURRENCY = 12;     // empresas en paralelo
const TIMEOUT_MS = 15000;   // una empresa que no responde no frena la tanda

const http = (opts) => this.helpers.httpRequest(opts);

// teladoc.wd503.myworkdayjobs.com/teladochealth_is_hiring
//   → https://teladoc.wd503.myworkdayjobs.com/wday/cxs/teladoc/teladochealth_is_hiring/jobs
function wdEndpoint(careersUrl) {
  const clean = String(careersUrl || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
  const parts = clean.split('/');
  const host = parts.shift();
  if (!host || !parts.length) return null;
  const tenant = host.split('.')[0];
  const site = parts[parts.length - 1];
  if (!tenant || !site) return null;
  return {
    api: `https://${host}/wday/cxs/${tenant}/${site}/jobs`,
    jobBase: `https://${host}/${parts.join('/')}`,
  };
}

async function pagesFor(api, term) {
  const found = [];
  for (let page = 0; page < MAX_PAGES; page++) {
    let res;
    try {
      res = await http({
        method: 'POST',
        url: api,
        json: true,
        timeout: TIMEOUT_MS,
        headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
        body: { appliedFacets: {}, limit: PAGE_SIZE, offset: page * PAGE_SIZE, searchText: term },
      });
    } catch (e) {
      break; // empresa que no responde: se saltea
    }
    const list = res?.jobPostings || [];
    found.push(...list);
    if (list.length < PAGE_SIZE) break;
  }
  return found;
}

async function fetchCompany(c) {
  const ep = wdEndpoint(c.careers_url);
  if (!ep) return [];
  const porTermino = await Promise.all(SEARCH_TERMS.map(t => pagesFor(ep.api, t)));
  const vistos = new Map();
  for (const lista of porTermino) {
    for (const j of lista) if (j.externalPath) vistos.set(j.externalPath, j);
  }
  return [...vistos.values()].map(j => ({ json: { company: c, jobBase: ep.jobBase, job: j } }));
}


const env = $('ENV').first().json.env;
const companiesEnvironment = env === 'local'
  ? $('Read Companies LOCAL').all()
  : $('Read Companies PROD').all();

const empresas = companiesEnvironment
  .map(i => i.json)
  .filter(c => (c.ats || '').toLowerCase() === 'workday' && c.careers_url);

const out = [];
for (let i = 0; i < empresas.length; i += CONCURRENCY) {
  const tanda = await Promise.all(empresas.slice(i, i + CONCURRENCY).map(fetchCompany));
  for (const r of tanda) out.push(...r);
}

return out;

// Get on Board: portal de empleo de LATAM, API pública y gratuita.
const http = (opts) => this.helpers.httpRequest(opts);

const CATEGORIES = [
  'programming',
  'data-science-analytics',
  'machine-learning-ai',
  'sysadmin-devops-qa',
  'mobile-developer',
];
const PER_PAGE = 100;
const MAX_PAGES = 6;

const out = [];

for (const cat of CATEGORIES) {
  for (let page = 1; page <= MAX_PAGES; page++) {
    let res;
    try {
      res = await http({
        method: 'GET',
        url: `https://www.getonbrd.com/api/v0/categories/${cat}/jobs`,
        qs: { per_page: PER_PAGE, page },
        json: true,
      });
    } catch (e) {
      break;
    }
    const data = res?.data || [];
    for (const job of data) out.push({ json: { job } });
    const total = res?.meta?.total_pages || 1;
    if (!data.length || page >= total) break;
  }
}

return out;

// =====================================================================
//  Normalize ATS  — 
//
//  Solo traduce Ashby / Greenhouse / Lever / Workable / Teamtailor al
//  formato comun y resuelve a que empresa pertenece cada aviso.
// =====================================================================

// El texto completo de la descripcion se usa SOLO adentro de este nodo,
// para decidir elegibilidad, y despues se descarta. Lo que viaja al resto
// del pipeline es un recorte corto mas dos banderas con el veredicto ya
// tomado. Con ~50.000 avisos por corrida, llevar el texto entero eran
// cientos de MB sostenidos en memoria y n8n se quedaba sin aire.
const MAX_DESC = 2000;
const cap = s => String(s || '').replace(/\s+/g, ' ').trim().slice(0, MAX_DESC);

// Mismas expresiones que usa Classify & Filter, aplicadas acá sobre el
// texto COMPLETO en vez de sobre el recorte.
const US_ONLY_RE = /(must|need to|required to)\s+(be\s+)?(based|located|live|reside)[^.]{0,40}(united states|u\.s\.|\busa\b)|(authorized|authorization|eligible)\s+to\s+work\s+in\s+the\s+(united states|u\.s\.)|u\.s\.\s+(citizen|work authorization)|citizen\/visa only/i;
const LATAM_HINT_RE = /argentin|buenos aires|latam|latin america|south america|\bamericas\b/i;
const VISA_NOT_REQ_RE = /not required/i;

// Teamtailor: ubicacion estructurada dentro de _jobposting
function ttLocations(jp) {
  const out = [];
  for (const p of jp?.jobLocation || []) {
    const a = p.address || {};
    const v = [a.addressLocality, a.addressRegion, a.addressCountry].filter(Boolean).join(', ');
    if (v) out.push(v);
  }
  return out.join(' | ');
}

function stripHtml(h) {
  return String(h || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ').trim();
}

// Greenhouse devuelve el content con las etiquetas escapadas (&lt;p&gt;).
// Se corta a 20000 nada mas para acotar casos patologicos: el recorte real
// lo hace cap(), despues de evaluar las banderas sobre este texto.
function ghContent(s) {
  const decoded = String(s || '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  return stripHtml(decoded).slice(0, 20000);
}

// El departamento viene con forma distinta en cada plataforma:
// texto, objeto con name, o array
function deptOf(v) {
  if (!v) return '';
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return deptOf(v[0]);
  return String(v.name || v.title || '').trim();
}

// Plataforma segun la forma de la oferta, no segun el indice del item
function detectAts(j) {
  if (j && j.shortcode && (j.url || j.shortlink)) return 'workable';
  if (j && j._jobposting) return 'teamtailor';
  if (j && j.absolute_url) return 'greenhouse';
  if (j && j.hostedUrl) return 'lever';
  return 'ashby';
}

// Slug de la empresa segun la URL de la oferta
function slugFromUrl(u) {
  const s = String(u || '');
  let m;
  if ((m = s.match(/jobs\.ashbyhq\.com\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/greenhouse\.io\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/jobs\.lever\.co\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/apply\.workable\.com\/([^\/?#]+)/i))) return m[1];
  if ((m = s.match(/https?:\/\/([^.\/]+)\.(?:[a-z]{2}\.)?teamtailor\.com/i))) return m[1];
  return '';
}

// Dominio de una URL, sin "www.".
// Hace falta porque algunas empresas configuran su board para redirigir a su
// propio sitio: Twindo publica en Greenhouse pero sus ofertas quedan en
// https://www.twindo.com/careers/?gh_jid=123, donde no aparece "greenhouse.io".
function hostOf(u) {
  const m = String(u || '').match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}

// Convierte una oferta de cualquier plataforma al mismo formato.
// description viene COMPLETA; el recorte se hace mas abajo.
function normalize(ats, j) {
  if (ats === 'workable') {
    const locs = (j.locations || [])
      .map(l => [l.city, l.region, l.country].filter(Boolean).join(', '))
      .filter(Boolean);
    const base = locs.length ? locs.join(' | ') : [j.city, j.state, j.country].filter(Boolean).join(', ');
    return {
      job_id: `wk:${j.shortcode}`,
      title: j.title || '',
      department: deptOf(j.department) || deptOf(j.departments),
      locations: [j.telecommuting ? 'Remote' : null, base].filter(Boolean).join(' | '),
      description: stripHtml(j.description),
      salary: '',
      published_at: String(j.published_on || j.created_at || '').slice(0, 10),
      apply_url: j.url || j.shortlink,
    };
  }
  if (ats === 'teamtailor') {
    const jp = j._jobposting || {};
    return {
      job_id: `tt:${jp.identifier?.value || j.id}`,
      title: j.title || jp.title || '',
      department: deptOf(j.department) || deptOf(jp.department),
      locations: ttLocations(jp),
      description: stripHtml(j.content_html),
      salary: '',
      published_at: String(j.date_published || jp.datePosted || '').slice(0, 10),
      apply_url: j.url,
    };
  }
  if (ats === 'greenhouse') return {
    job_id: `gh:${j.id}`,
    title: j.title || '',
    department: deptOf(j.departments) || deptOf(j.department),
    locations: j.location?.name || '',
    description: ghContent(j.content),
    salary: '',
    published_at: (j.first_published || j.updated_at || '').slice(0, 10),
    apply_url: j.absolute_url,
  };
  if (ats === 'lever') {
    const sr = j.salaryRange;
    return {
      job_id: `lever:${j.id}`,
      title: j.text || '',
      department: deptOf(j.categories?.department) || deptOf(j.categories?.team),
      locations: [...new Set([j.categories?.location, ...(j.categories?.allLocations || [])].filter(Boolean))].join(' | '),
      description: j.descriptionPlain || '',
      salary: sr && sr.max ? `$${Math.round(sr.min / 1000)}K - $${Math.round(sr.max / 1000)}K` : '',
      published_at: j.createdAt ? new Date(j.createdAt).toISOString().slice(0, 10) : '',
      apply_url: j.hostedUrl,
    };
  }
  // Ashby: el pais principal va en location, el resto en secondaryLocations
  return {
    job_id: `ashby:${j.id}`,
    title: j.title || '',
    department: deptOf(j.department) || deptOf(j.team),
    locations: [
      (j.isRemote || j.workplaceType === 'Remote') ? 'Remote' : null,
      j.location,
      ...(j.secondaryLocations || []).map(
        l => l && (l.location || l.address?.postalAddress?.addressCountry)
      ),
    ].filter(Boolean).join(' | '),
    description: j.descriptionPlain || '',
    salary: j.compensation?.scrapeableCompensationSalarySummary || j.compensation?.compensationTierSummary || '',
    published_at: (j.publishedAt || '').slice(0, 10),
    apply_url: j.jobUrl,
  };
}

// ---- Indices de empresas ----
const env = $('ENV').first().json.env;
const companies = env === 'local'
  ? $('Read Companies LOCAL').all()
  : $('Read Companies PROD').all();

const bySlug = new Map();
companies.forEach(it => {
  const c = it.json || {};
  if (c.slug) bySlug.set(String(c.slug).toLowerCase(), c);
});

// Segundo indice, por dominio propio de la empresa. Los dominios de los
// propios ATS quedan afuera a proposito: si no, cien empresas se mapearian
// al mismo host.
const ATS_HOSTS = /greenhouse\.io|lever\.co|ashbyhq\.com|workable\.com|teamtailor\.com|myworkdayjobs\.com|workday/i;
const byHost = new Map();
companies.forEach(it => {
  const c = it.json || {};
  const h = hostOf(c.careers_url);
  if (h && !ATS_HOSTS.test(h) && !byHost.has(h)) byHost.set(h, c);
});

const out = [];

$input.all().forEach((item, i) => {
  // Algunas plataformas devuelven el JSON como texto: lo parseamos
  let body = item.json;
  if (typeof body?.data === 'string') {
    try { body = JSON.parse(body.data); } catch (e) { body = {}; }
  }

  // Ashby, Greenhouse y Workable devuelven { jobs: [...] }; Teamtailor, { items: [...] };
  // Lever devuelve un array que n8n ya partio en un item por oferta
  let raws = [];
  if (Array.isArray(body?.jobs)) raws = body.jobs;
  else if (Array.isArray(body?.items)) raws = body.items;
  else if (body?.hostedUrl || body?.absolute_url || body?.jobUrl) raws = [body];
  if (!raws.length) return;

  // Empresa de respaldo, solo si no se puede resolver por URL ni por dominio
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const fallback = companies[p?.item ?? i]?.json || {};

  for (const r of raws) {
    const ats = detectAts(r);
    const o = normalize(ats, r);
    if (!o.apply_url) continue;

    // Tres escalones: slug en la URL del ATS, dominio propio, respaldo
    const c = bySlug.get(slugFromUrl(o.apply_url).toLowerCase())
           || byHost.get(hostOf(o.apply_url))
           || fallback;
    if (!c.slug) continue;

    // Las banderas se calculan sobre el texto COMPLETO, antes de recortarlo.
    const full = String(o.description || '');

    out.push({ json: {
      job_id: o.job_id,
      source: ats,
      title: o.title,
      department: o.department || '',
      locations: o.locations,
      description: cap(full),
      us_only: US_ONLY_RE.test(full),
      latam_hint: LATAM_HINT_RE.test(full),
      visa_not_required: VISA_NOT_REQ_RE.test(full),
      salary: o.salary,
      salary_max_k: '',
      published_at: o.published_at,
      apply_url: o.apply_url,
      company: c.company,
      company_slug: c.slug,
      company_id: c.company_id || '',
      company_hq: c.hq || '',
      company_size: c.size || '',
      company_stage: c.stage || '',
      company_linkedin: c.linkedin_slug ? `https://www.linkedin.com/company/${c.linkedin_slug}` : '',
    }});
  }
});

return out;

// =====================================================================
//  Normalize Workday  —  reemplaza el contenido de "Filter Workday"
//
//  Solo traduce el formato de Workday al formato comun.
//  NO filtra ni clasifica: eso lo hace "Classify & Filter".
// =====================================================================

// "Posted 24 Days Ago" -> fecha. Workday no publica la fecha real.
function wdPosted(s) {
  const t = String(s || '');
  let days = null;
  if (/today/i.test(t)) days = 0;
  else if (/yesterday/i.test(t)) days = 1;
  else {
    const m = t.match(/(\d+)\+?\s*days?/i);
    if (m) days = parseInt(m[1], 10);
  }
  if (days === null) return '';
  return new Date(Date.now() - days * 86400000).toISOString().slice(0, 10);
}

const out = [];

for (const item of $input.all()) {
  const { company: c, jobBase, job: j } = item.json;
  if (!c || !j) continue;

  const id = (String(j.externalPath).match(/_([A-Z0-9]+)$/) || [])[1] || j.externalPath;

  out.push({ json: {
    job_id: `wd:${c.slug}:${id}`,
    source: 'workday',
    title: j.title || '',
    department: '',
    locations: j.locationsText || '',
    description: '',
    salary: '',
    salary_max_k: '',
    published_at: wdPosted(j.postedOn),
    apply_url: jobBase + j.externalPath,
    company: c.company,
    company_slug: c.slug,
    company_id: c.company_id || '',
    company_hq: c.hq || '',
    company_size: c.size || '',
    company_stage: c.stage || '',
    company_linkedin: c.linkedin_slug ? `https://www.linkedin.com/company/${c.linkedin_slug}` : '',
  }});
}

return out;

// =====================================================================
//  Normalize YC  —  reemplaza el contenido de "Filter YC"
//
//  Solo traduce el formato de Work at a Startup al formato comun.
//  NO filtra ni clasifica, salvo dos cosas que son propias de YC:
//    - empresas que no estan activas
//    - avisos marcados como pasantia, que YC trae en un campo estructurado
//      (mas confiable que buscar "intern" en el titulo)
// =====================================================================

const out = [];

for (const item of $input.all()) {
  const c = item.json;
  if (c.status !== 'Active') continue;

  const li = (c.linkedin_url || '').replace(/\/+$/, '');

  for (const j of c.jobs || []) {
    if (j.type === 'Internship') continue;

    out.push({ json: {
      job_id: `yc:${j.id}`,
      source: 'yc',
      title: j.title || '',
      // YC trae el area como campo estructurado: vale como departamento
      department: j.role || '',
      locations: j.location || '',
      // lo unico que YC dice sobre elegibilidad esta en visa
      description: j.visa || '',
      salary: j.salary_range || '',
      salary_max_k: '',
      published_at: '',
      apply_url: j.url,
      company: c.name,
      company_slug: c.slug,
      company_id: '',
      company_hq: c.all_locations || '',
      company_size: c.team_size || '',
      company_stage: c.batch || '',
      company_linkedin: li,
    }});
  }
}

return out;

// =====================================================================
//  Normalize GOB  —  reemplaza el contenido de "Filter GOB"
//
//  Solo traduce el formato de Get on Board al formato comun.
//  NO filtra ni clasifica.
//
//  OJO con dos cosas propias de esta fuente:
//
//  1) El aviso no trae el nombre de la empresa, solo su id. Antes se pedia
//     aca, despues de filtrar, para no gastar llamadas. Ahora se pide en el
//     nodo "Resolve GOB company", que corre DESPUES de Classify & Filter:
//     se siguen haciendo pocas llamadas, y ademas quedan menos que antes.
//
//  2) Get on Board trae la elegibilidad estructurada en remote_modality.
//     Cuando dice fully_remote le creemos a ese campo y no a nuestro parseo
//     del texto: va en match_override.
//
//  3) Tambien trae seniority y tags ya clasificados a mano por ellos. Eso es
//     mejor que cualquier inferencia nuestra, asi que se los pasamos al
//     modelo adentro del texto en vez de tirarlos.
// =====================================================================

const MAX_DESC = 2000;

function stripHtml(h) {
  return String(h || '')
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Los campos de Get on Board vienen a veces como texto, a veces como array,
// a veces como { data: { id, name } }. Esto los aplana sin tener que saber cual.
function txtOf(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number') return String(v);
  if (Array.isArray(v)) return v.map(txtOf).filter(Boolean).join(', ');
  if (typeof v === 'object') return txtOf(v.name ?? v.title ?? v.data ?? '');
  return '';
}

// El texto del aviso vive partido en varios campos. Los juntamos, y adelante
// ponemos lo que Get on Board ya clasifico: al modelo le sirve mas una linea
// que diga "Seniority: senior" que mil palabras de marketing.
function descOf(a) {
  const pistas = [
    txtOf(a.seniority) && `Seniority: ${txtOf(a.seniority)}`,
    txtOf(a.tags)      && `Tags: ${txtOf(a.tags)}`,
    txtOf(a.modality)  && `Modality: ${txtOf(a.modality)}`,
  ].filter(Boolean).join(' · ');

  const cuerpo = [a.description, a.functions, a.desirable]
    .filter(Boolean)
    .map(stripHtml)
    .filter(Boolean)
    .join(' ');

  return [pistas, cuerpo].filter(Boolean).join(' — ').slice(0, MAX_DESC);
}

// Los sueldos vienen mensuales en USD
function salaryInfo(a) {
  const min = Number(a.min_salary) || 0;
  const max = Number(a.max_salary) || 0;
  if (!max) return { text: '', maxK: '' };
  return {
    text: `$${min} - $${max} USD/mes`,
    maxK: Math.round((max * 12) / 1000),
  };
}

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const j = item.json.job || {};
  const a = j.attributes || {};
  const title = a.title || '';
  if (!title || !j.id || seen.has(j.id)) continue;
  seen.add(j.id);

  const countries = (a.countries || []).map(String);
  const sal = salaryInfo(a);

  out.push({ json: {
    job_id: `gob:${j.id}`,
    source: 'getonbrd',
    title,
    department: txtOf(a.category_name),
    locations: [...new Set([a.remote ? 'Remote' : null, ...countries].filter(Boolean))].join(' | '),
    description: descOf(a),
    salary: sal.text,
    salary_max_k: sal.maxK,
    published_at: a.published_at
      ? new Date(a.published_at * 1000).toISOString().slice(0, 10)
      : '',
    apply_url: j.links?.public_url || '',
    company: '',                 // se completa en "Resolve GOB company"
    company_slug: '',
    company_id: null,
    company_hq: countries.filter(c => !/^remote$/i.test(c)).join(', '),
    company_size: '',
    company_stage: '',
    company_linkedin: '',
    // propios de esta fuente
    gob_company_id: a.company?.data?.id || '',
    match_override: a.remote_modality === 'fully_remote' ? ['yes', 'fully_remote'] : null,
  }});
}

return out;

// =====================================================================
//  Resolve GOB company  —  NODO NUEVO
//  Va entre "Classify & Filter" y "Filter ignored".
//
//  Get on Board no trae el nombre de la empresa en el aviso, solo su id.
//  Este nodo lo resuelve con una llamada por empresa, y de paso descarta
//  consultoras y outsourcing.
//
//  Corre DESPUES del filtrado a proposito: solo se piden los nombres de los
//  avisos que sobrevivieron, que son unos pocos. Los items de las otras
//  fuentes pasan de largo sin tocarse.
// =====================================================================

const http = (opts) => this.helpers.httpRequest(opts);

// Consultoras y outsourcing: contratan para terceros, no son producto.
// Get on Board esta lleno de estas, hay que ir sumandolas a mano.
const STAFFING = /^(bc tecnolog|i2b|rapidseedbox|2brains|kibernum|sonda|everis|globant|ntt data|accenture|tcs|infosys|sophos solutions|apiux|coasin|nisum|itsoft|zentyalabs|factor it|zaelot|improving|lisit|witi|lead gen team|we built it|one click technology)/i;

const nameCache = new Map();

async function companyName(id) {
  if (!id) return '';
  if (nameCache.has(id)) return nameCache.get(id);
  let n = '';
  try {
    const r = await http({
      method: 'GET',
      url: `https://www.getonbrd.com/api/v0/companies/${id}`,
      json: true,
    });
    n = r?.data?.attributes?.name || '';
  } catch (e) {
    n = '';
  }
  nameCache.set(id, n);
  return n;
}

const out = [];

for (const item of $input.all()) {
  const o = { ...item.json };

  // Las demas fuentes pasan de largo; solo se limpia el campo auxiliar
  if (o.source !== 'getonbrd') {
    delete o.gob_company_id;
    out.push({ json: o });
    continue;
  }

  const name = await companyName(o.gob_company_id);
  if (!name || STAFFING.test(name)) continue;

  o.company = name;
  delete o.gob_company_id;
  out.push({ json: o });
}

return out;

// Deduplica por empresa + titulo. El mismo puesto puede llegar por el ATS
// de la empresa y ademas por YC o Get on Board, con ids distintos. Y hay
// empresas que publican el mismo puesto una vez por pais.
// Gana la mejor fuente, no la primera, y se le completan los campos vacios
// con los datos de los otros.

// Cuanto mas bajo, mejor fuente. El criterio es el valor para el candidato:
// un link que va derecho al board de la empresa vale mas que uno que pasa
// por un intermediario o que exige crearse una cuenta.
const SOURCE_RANK = {
  ashby: 1,
  greenhouse: 1,
  lever: 1,
  workable: 2,
  teamtailor: 2,
  workday: 3,     // directo, pero con datos mas pobres
  getonbrd: 4,    // trae sueldo, pero el link pasa por su sitio
  yc: 5,          // para postularte necesitas cuenta de Work at a Startup
};
const rankOf = s => SOURCE_RANK[String(s || '').toLowerCase()] ?? 9;

// Campos que se completan desde el perdedor cuando el ganador los tiene vacios
const FILLABLE = [
  'description',
  'salary', 'salary_max_k', 'published_at', 'department', 'locations',
  'company_id', 'company_slug', 'company_hq', 'company_size', 'company_stage',
  'company_linkedin', 'linkedin_people_ar',
];

const isEmpty = v => v === '' || v === null || v === undefined;
const filledScore = o => FILLABLE.reduce((n, f) => n + (isEmpty(o[f]) ? 0 : 1), 0);

// Cuanto mas bajo, mas fuerte la señal geografica
const MATCH_RANK = {
  argentina_in_location: 1,
  argentina_in_title: 2,
  latam_in_location: 3,
  latam_in_title: 4,
  latam_country_remote: 5,
  fully_remote: 6,
  remote_visa_not_required: 7,
  remote_no_country: 8,
  latam_in_description: 9,
};
const matchRank = o =>
  (o.accepts_argentina === 'yes' ? 0 : 100) + (MATCH_RANK[o.location_match] ?? 50);

// ---- Agrupar por empresa + titulo ----
const norm = s => String(s || '').toLowerCase().trim().replace(/\s+/g, ' ');
const groups = new Map();

for (const item of $input.all()) {
  const o = { ...item.json };
  delete o.gob_company_id;

  const key = `${norm(o.company)}|${norm(o.title)}`;
  if (!key.replace('|', '')) continue;

  const g = groups.get(key);
  if (g) g.push(o);
  else groups.set(key, [o]);
}

// ---- Elegir ganador, unir ubicaciones y completar huecos ----
const out = [];

for (const group of groups.values()) {
  if (group.length === 1) {
    out.push({ json: group[0] });
    continue;
  }

  // Mejor fuente; a igual fuente, el que trae mas datos
  const ordered = [...group].sort((a, b) => {
    const r = rankOf(a.source) - rankOf(b.source);
    if (r !== 0) return r;
    return filledScore(b) - filledScore(a);
  });

  const winner = { ...ordered[0] };

  for (const l of ordered.slice(1)) {
    for (const f of FILLABLE) {
      if (isEmpty(winner[f]) && !isEmpty(l[f])) winner[f] = l[f];
    }
    // Quedarse con la señal geografica mas fuerte: si una fuente dice
    // Argentina explicitamente y la otra solo dice "Remote", vale la primera
    if (matchRank(l) < matchRank(winner)) {
      winner.accepts_argentina = l.accepts_argentina;
      winner.location_match = l.location_match;
    }
  }

  // Unir las ubicaciones de todo el grupo, sin repetir.
  // Sezzle publica el mismo puesto una vez por pais: asi queda uno solo
  // que dice Argentina, Brasil, Chile, Mexico y Colombia a la vez.
  const parts = [];
  for (const o of ordered) {
    for (const p of String(o.locations || '').split(/\s*[|\/;]\s*/)) {
      const v = p.trim();
      if (v && !parts.includes(v)) parts.push(v);
    }
  }
  if (parts.length) winner.locations = parts.join(' | ');

  winner.dedup_count = `dedup:${group.length}`;
  out.push({ json: winner });
}

return out;

// =====================================================================
//  Filtrar  —  decide QUE ENTRA al indice, nada mas.
//
//  Lo que este nodo descarta se pierde para siempre, asi que solo descarta
//  cosas que no son opinables:
//
//    - avisos rotos (sin id, sin titulo, sin link de postulacion)
//    - duplicados dentro de la misma corrida
//    - elegibilidad geografica, que es la compuerta de volumen
//
//  Todo lo demas —si es ingenieria o ventas, que nivel es, si la empresa es
//  una consultora, si es un evergreen, si el sueldo alcanza, si el aviso es
//  viejo— es configuracion del usuario o trabajo del clasificador. Una
//  etiqueta mal puesta se corrige reclasificando; un descarte no se corrige.
//
//  POR QUE LA GEOGRAFIA SE QUEDA ACA Y NO VA AL MODELO:
//  entran ~51.700 avisos por corrida y el chequeo geografico deja pasar el
//  4,5%. Si esa decision la tomara el modelo habria que clasificar los 51.700
//  todos los dias. Es la unica razon, y es de costo, no de diseno.
//
//  PENDIENTE: esta logica esta escrita Argentina-primero y el producto es
//  para toda LATAM. La forma de arreglarlo sin que cueste una fortuna es una
//  tabla `locations` cacheada: el modelo clasifica cada string de ubicacion
//  UNA vez, no cada aviso. Ver el contador ubicaciones_distintas del resumen.
//
//  Las lineas marcadas // [INSTR] son instrumentacion: cuentan descartes y
//  emiten un item de resumen al principio. Se sacan borrandolas.
// =====================================================================

const LATAM = /latam|latin america|south america|\bamericas\b/i;
const GLOBAL = /\b(anywhere|worldwide|global)\b/i;
const REMOTE_ONLY = /^(remote|remoto|fully remote)$/i;
const US_ONLY = /(must|need to|required to)\s+(be\s+)?(based|located|live|reside)[^.]{0,40}(united states|u\.s\.|\busa\b)|(authorized|authorization|eligible)\s+to\s+work\s+in\s+the\s+(united states|u\.s\.)|u\.s\.\s+(citizen|work authorization)|citizen\/visa only/i;

const LATAM_COUNTRY = /\b(argentin|brazil|brasil|colombia|chile|uruguay|per[úu]|paraguay|bolivia|ecuador|venezuela|(?<!new )m[ée]xico|costa rica|panam[áa]|guatemala)\b|\b(ARG|BRA|COL|CHL|URY|PER|MEX|CRI)\b|\b(bogot[áa]|medell[íi]n|barranquilla|cartagena|s[ãa]o paulo|rio de janeiro|porto alegre|belo horizonte|curitiba|florian[óo]polis|joinville|recife|montevideo|asunci[óo]n|guadalajara|monterrey|cdmx|quito|guayaquil|san salvador|tegucigalpa|managua)\b/i;
const OTHER_LATAM_CODE = /\b(BR|CO|CL|UY|PE|MX|EC|BO|PY|VE|CR)\b/;
const NY_STREET = /ave(nue)?\.?\s+of\s+(the\s+)?americas/ig;

// "Americas" a secas es ambiguo; "LATAM" y "Latin America" no lo son.
const AMERICAS_GENERIC = /\bamericas\b/i;
const EXPLICIT_LATAM   = /latam|latin america|south america/i;
const NORTH_AM_COUNTRY = /\b(usa|u\.s\.a?\.?|united states|canada|canad[áa])\b/i;
// El titulo nombra EE.UU. aunque la ubicacion diga solo "Remote"
const US_IN_TITLE = /\busa\b|\bu\.s\.a?\.|\bunited states\b/i;

// TRANSITORIO — paso 3.4 del plan.
// priority y role_category son columnas de `jobs` que la app todavia puede
// estar leyendo, y role_category es un enum. Dejar de escribirlas sin tocar
// la app rompe Hunter. Se van las tres cuando el orden se calcule al leer,
// desde el array `levels` del usuario.
const MANAGER = /manager|gerente|jefe|head of|director|\bvp\b|vice president|\bcto\b/i;
const LEAD = /lead|l[íi]der|staff|principal|forward deployed|product engineer|founding/i;
const PRIORITY = { manager: 1, lead_staff: 2, ic: 3 };

// Las descripciones vienen en HTML crudo y pesan 10-20 KB cada una.
// Se guardan limpias y recortadas: el payload baja ~90% y el modelo
// no paga tokens por etiquetas ni por el boilerplate del final.
const MAX_DESC_CHARS = 4000;
function limpiarDesc(s) {
  if (!s) return '';
  return String(s)
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;|&rsquo;/g, "'")
    .replace(/&quot;|&ldquo;|&rdquo;/g, '"')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, MAX_DESC_CHARS);
}

// ---------------------------------------------------------------------
function classify(rawLoc, extra, title, o) {
  const t = title || '';
  const loc = String(rawLoc || '').replace(NY_STREET, '');

  // "Americas (USA or Canada)": nombra la region pero enumera paises de afuera.
  // Va primero porque es una trampa, no una senal.
  if (AMERICAS_GENERIC.test(loc) && NORTH_AM_COUNTRY.test(loc)
      && !EXPLICIT_LATAM.test(loc) && !LATAM_COUNTRY.test(loc)) {
    return ['no', 'descartado_americas_us_ca'];
  }

  // Cualquier pais o ciudad de LATAM nombrado en la ubicacion la hace elegible.
  // Antes esto era "si dice Argentina" y ademas exigia que dijera "remote":
  // un aviso presencial en Bogota se descartaba. El producto es para toda la
  // region, asi que ese aviso entra y despues cada usuario filtra por su pais.
  if (LATAM_COUNTRY.test(loc)) return ['yes', 'latam_country_in_location'];

  // Codigos de dos letras: "AR" solo seria ambiguo (Arkansas). Si viene con
  // otro codigo LATAM al lado, es Argentina y no Estados Unidos.
  if (/\bAR\b/.test(loc) && OTHER_LATAM_CODE.test(loc)) return ['yes', 'latam_code_in_location'];

  // La region nombrada como region
  if (LATAM.test(loc)) return ['yes', 'latam_in_location'];
  if (LATAM.test(t) || LATAM_COUNTRY.test(t)) return ['yes', 'latam_in_title'];

  // "Team Lead, Android Core Product - Boise, ID, USA" con ubicacion "Remote"
  if (US_IN_TITLE.test(t)) return ['no', 'descartado_us_en_titulo'];

  // La bandera viene calculada sobre el texto completo en Normalize.
  // El test sobre `extra` queda de respaldo para las fuentes que todavia
  // no la mandan (Workday, YC, Get on Board).
  const restricted = (o && o.us_only === true) || US_ONLY.test(extra);
  const parts = loc.split(/\s*[|\/;]\s*/).map(p => p.trim()).filter(Boolean);
  const remoteOnly = parts.length > 0 && parts.every(p => REMOTE_ONLY.test(p) || GLOBAL.test(p));

  if (remoteOnly && !restricted) {
    return ((o && o.visa_not_required === true) || /not required/i.test(extra))
      ? ['maybe', 'remote_visa_not_required']
      : ['maybe', 'remote_no_country'];
  }

  const hasCountryInfo = parts.some(p => !REMOTE_ONLY.test(p) && !GLOBAL.test(p));
  if (!hasCountryInfo && (LATAM.test(extra) || LATAM_COUNTRY.test(extra)) && !restricted) {
    return ['maybe', 'latam_in_description'];
  }

  return ['no', restricted ? 'descartado_us_only_en_descripcion' : 'descartado_sin_senal_latam'];
}

function salaryMaxK(s) {
  const m = (s || '').match(/\$([\d.,]+)\s*(K?)\s*[-–]\s*\$([\d.,]+)\s*(K?)/i);
  if (!m) return null;
  let max = parseFloat(m[3].replace(/,/g, ''));
  if (!m[4]) max = max / 1000;
  return max < 20 ? Math.round(max * 12) : max;
}

// TRANSITORIO — ver el comentario de PRIORITY arriba.
function roleCategory(title) {
  if (MANAGER.test(title)) return 'manager';
  if (LEAD.test(title)) return 'lead_staff';
  return 'ic';
}

function guessHq(locations) {
  const count = {};
  for (const raw of locations) {
    for (const p of String(raw || '').split(/\s*[|\/;]\s*/)) {
      const v = p.trim();
      if (!v || /remote|remoto|anywhere|worldwide|global|latam|latin america/i.test(v)) continue;
      count[v] = (count[v] || 0) + 1;
    }
  }
  const top = Object.entries(count).sort((a, b) => b[1] - a[1])[0];
  return top ? top[0] : '';
}

// ---------------------------------------------------------------------
// [INSTR] contadores
const drops = {};
const motivosNoElegible = {};
const ubicaciones = new Set();
const bump = (obj, k) => { if (!k) return; obj[k] = (obj[k] || 0) + 1; };
const drop = (motivo) => bump(drops, motivo);
// [INSTR] fin

const items = $input.all().map(i => i.json || {});

const locsByCompany = {};
for (const o of items) {
  if (!o.company_slug) continue;
  (locsByCompany[o.company_slug] = locsByCompany[o.company_slug] || []).push(o.locations);
}

const out = [];
const seen = new Set();

for (const o of items) {
  if (!o.job_id) { drop('sin_job_id'); continue; }                        // [INSTR]
  if (seen.has(o.job_id)) { drop('duplicado_en_corrida'); continue; }     // [INSTR]
  seen.add(o.job_id);

  ubicaciones.add(String(o.locations || '').trim().toLowerCase());        // [INSTR]

  const title = String(o.title || '');
  if (!title) { drop('sin_titulo'); continue; }                           // [INSTR]
  if (!o.apply_url) { drop('sin_link'); continue; }                       // [INSTR]

  // OJO: classify() recibe la descripcion CRUDA, sin recortar.
  // Con la version recortada se perderian las detecciones de
  // "must be based in the US" que viven al final del texto.
  const [accepts, match] = Array.isArray(o.match_override)
    ? o.match_override
    : classify(o.locations, o.description, title, o);
  if (accepts === 'no') {
    drop('no_elegible_latam');                                            // [INSTR]
    bump(motivosNoElegible, match || 'sin_motivo');                       // [INSTR]
    continue;
  }

  const maxK = (o.salary_max_k === '' || o.salary_max_k === null || o.salary_max_k === undefined)
    ? salaryMaxK(o.salary)
    : Number(o.salary_max_k);

  const role = roleCategory(title);
  const li = o.company_linkedin || '';

  out.push({ json: {
    job_id: o.job_id,
    company_id: o.company_id ?? '',
    priority: PRIORITY[role],
    role_category: role,
    accepts_argentina: accepts,
    location_match: match,
    company: o.company || '',
    company_slug: o.company_slug || '',
    company_hq: o.company_hq || guessHq(locsByCompany[o.company_slug] || []),
    company_size: o.company_size || '',
    company_stage: o.company_stage || '',
    title: title.trim(),
    department: o.department || '',
    description: limpiarDesc(o.description),
    salary: o.salary || '',
    salary_max_k: (maxK === null || Number.isNaN(maxK)) ? '' : maxK,
    locations: o.locations || '',
    published_at: o.published_at || '',
    apply_url: o.apply_url || '',
    company_linkedin: li,
    linkedin_people_ar: li ? `${li}/people/?facetGeoRegion=100446943` : '',
    source: o.source || '',
    gob_company_id: o.gob_company_id || '',
  }});
}

// [INSTR] resumen como primer item. Muere en "Deduplicate and complete"
// porque no tiene company ni title, asi que no llega a la base.
out.unshift({ json: {
  __RESUMEN__: true,
  entrada: items.length,
  ubicaciones_distintas: ubicaciones.size,
  pasaron: out.length,
  descartados: Object.values(drops).reduce((a, b) => a + b, 0),
  descartes_por_motivo: Object.fromEntries(
    Object.entries(drops).sort((a, b) => b[1] - a[1])
  ),
  motivos_no_elegible: Object.fromEntries(
    Object.entries(motivosNoElegible).sort((a, b) => b[1] - a[1])
  ),
}});
// [INSTR] fin

console.log('=== RESUMEN ===\n' + JSON.stringify(out[0].json, null, 2));

return out;
